function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof RAILWAYS_INFO&&(n.innerHTML=RAILWAYS_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderHistory(){if("undefined"==typeof ENGINEERING_MARVELS)return;const n=document.getElementById("rail-overview"),e=document.getElementById("rail-mechanisms"),t=document.getElementById("rail-status");n&&(n.innerHTML=`<strong>Overview:</strong> ${ENGINEERING_MARVELS.overview}`),e&&(e.innerHTML=`<strong>Engineering Innovations:</strong> ${ENGINEERING_MARVELS.mechanisms}`),t&&(t.innerHTML=`<strong>Conservation Status:</strong> ${ENGINEERING_MARVELS.conservationStatus}`)}function renderLines(){const n=document.getElementById("lines-grid");n&&"undefined"!=typeof MOUNTAIN_RAILWAYS&&(n.innerHTML=MOUNTAIN_RAILWAYS.map(n=>`\n        <div class="line-card">\n            <img src="${n.image}" alt="${n.name}" loading="lazy" />\n            <div class="line-card-body">\n                <div class="line-header">\n                    <h3>${n.name} ${n.icon}</h3>\n                    <span class="unesco-badge">UNESCO (${n.unescoYear})</span>\n                </div>\n                <p class="route-lbl"><strong>Route:</strong> ${n.route} (${n.length})</p>\n                <p class="gauge-lbl"><strong>Gauge:</strong> ${n.gauge} | <strong>Highest:</strong> ${n.highestPoint}</p>\n                <p>${n.description}</p>\n                <div class="highlights-box">\n                    <strong>Engineering Highlights:</strong>\n                    <ul>\n                        ${n.highlights.map(n=>`<li>✨ ${n}</li>`).join("")}\n                    </ul>\n                </div>\n            </div>\n        </div>\n    `).join(""))}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof GALLERY_IMAGES&&(n.innerHTML=GALLERY_IMAGES.map(n=>`\n        <div class="gallery-card">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" />\n            <p>${n.caption}</p>\n        </div>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderHistory(),renderLines(),renderGallery(),initThemeToggle()});